 *   1. Rincian EXP quest (EXP dasar + multiplier + bonus achievement)
 *   2. Tombol reset / tolak permintaan reset password di halaman admin
 *   3. Penolakan request reset password untuk identitas yang tidak terdaftar
 *
 * CARA PAKAI:
 *   1. Upload file ini ke:  school_quest_deploy/public/inject.php
 *   2. Buka:  https://sk0011jb6j.skipper.my.id/school_quest_deploy/public/inject.php?key=sq2026hotfix2
 *   3. Setelah selesai, HAPUS file inject.php dari server.
 */

@set_time_limit(300);
@ini_set('memory_limit', '512M');
header('Content-Type: text/html; charset=utf-8');

$TOKEN = 'sq2026hotfix2';

$key = isset($_GET['key']) ? (string) $_GET['key'] : '';
if (!hash_equals($TOKEN, $key)) {
    http_response_code(403);
    echo '<!DOCTYPE html><html lang="id"><body style="font-family:system-ui,sans-serif;background:#0f172a;color:#e2e8f0;padding:40px;">'
        . '<h2 style="color:#f87171;">Akses ditolak</h2>'
        . '<p>Tambahkan kunci pada URL:</p>'
        . '<p><code style="background:#1e293b;padding:6px 10px;border-radius:6px;">?key=' . htmlspecialchars($TOKEN, ENT_QUOTES) . '</code></p>'
        . '</body></html>';
    exit;
}

function sq_h($value)
{
    return htmlspecialchars((string) $value, ENT_QUOTES, 'UTF-8');
}

function sq_find_app_root()
{
    $bases = [__DIR__, dirname(__DIR__), dirname(__DIR__, 2), dirname(__DIR__, 3), dirname(__DIR__, 4)];
    $found = [];
    foreach ($bases as $base) {
        $candidates = [$base, rtrim($base, '/\\') . '/school_quest_deploy'];
        foreach ($candidates as $candidate) {
            $candidate = rtrim($candidate, '/\\');
            if (is_file($candidate . '/artisan') && is_dir($candidate . '/app') && is_dir($candidate . '/public')) {
                $found[$candidate] = strlen($candidate);
            }
        }
    }
    if (empty($found)) {
        return null;
    }
    // Pilih path terpanjang (paling spesifik) agar tidak salah memilih folder induk.
    arsort($found);
    return array_key_first($found);
}

function sq_copy_dir($src, $dst, &$count, &$errors)
{
    if (!is_dir($src)) {
        return;
    }
    if (!is_dir($dst) && !@mkdir($dst, 0777, true) && !is_dir($dst)) {
        $errors[] = 'Tidak bisa membuat folder: ' . $dst;
        return;
    }
    @chmod($dst, 0777);

    $items = @scandir($src);
    if ($items === false) {
        $errors[] = 'Tidak bisa membaca folder: ' . $src;
        return;
    }

    foreach ($items as $item) {
        if ($item === '.' || $item === '..') {
            continue;
        }
        $from = $src . '/' . $item;
        $to = $dst . '/' . $item;
        if (is_dir($from)) {
            sq_copy_dir($from, $to, $count, $errors);
        } elseif (is_file($from)) {
            if (@copy($from, $to)) {
                @chmod($to, 0666);
                $count++;
            } else {
                $errors[] = 'Gagal menyalin: ' . $to;
            }
        }
    }
}

function sq_clear_cache($appRoot)
{
    $cleared = 0;
    $patterns = [
        $appRoot . '/storage/framework/views/*.php',
        $appRoot . '/bootstrap/cache/*.php',
        $appRoot . '/storage/framework/cache/data/*/*/*',
    ];
    foreach ($patterns as $pattern) {
        $files = @glob($pattern);
        if (!is_array($files)) {
            continue;
        }
        foreach ($files as $file) {
            if (is_file($file) && @unlink($file)) {
                $cleared++;
            }
        }
    }
    return $cleared;
}

$appRoot = sq_find_app_root();

if (!$appRoot) {
    http_response_code(500);
    echo '<!DOCTYPE html><html lang="id"><body style="font-family:system-ui,sans-serif;background:#0f172a;color:#e2e8f0;padding:40px;">'
        . '<h2 style="color:#f87171;">Folder aplikasi Laravel tidak ditemukan</h2>'
        . '<p>Upload file <code>inject.php</code> ini ke folder:</p>'
        . '<p><code style="background:#1e293b;padding:6px 10px;border-radius:6px;">school_quest_deploy/public/</code></p>'
        . '<p>Lalu buka kembali URL dengan <code>?key=' . htmlspecialchars($TOKEN, ENT_QUOTES) . '</code>.</p>'
        . '</body></html>';
    exit;
}

if (!class_exists('ZipArchive')) {
    http_response_code(500);
    echo '<!DOCTYPE html><html lang="id"><body style="font-family:system-ui,sans-serif;background:#0f172a;color:#e2e8f0;padding:40px;">'
        . '<h2 style="color:#f87171;">Ekstensi PHP ZipArchive tidak aktif</h2>'
        . '<p>Aktifkan ekstensi <code>zip</code> pada hosting, lalu buka kembali halaman ini.</p>'
        . '</body></html>';
    exit;
}

$payload = base64_decode('', true);
if ($payload === false || strlen($payload) < 100) {
    http_response_code(500);
    echo '<h2 style="font-family:system-ui,sans-serif;color:#f87171;">Paket perbaikan rusak (base64 tidak valid).</h2>';
    exit;
}

$tmpZip = tempnam(sys_get_temp_dir(), 'sqh');
if ($tmpZip === false || @file_put_contents($tmpZip, $payload) === false) {
    http_response_code(500);
    echo '<h2 style="font-family:system-ui,sans-serif;color:#f87171;">Gagal menulis paket sementara ke server.</h2>';
    exit;
}
unset($payload);

$zip = new ZipArchive();
if ($zip->open($tmpZip) !== true) {
    @unlink($tmpZip);
    http_response_code(500);
    echo '<h2 style="font-family:system-ui,sans-serif;color:#f87171;">Gagal membuka paket ZIP.</h2>';
    exit;
}

// ---------------------------------------------------------------
// Backup file yang akan ditimpa (hanya source code, bukan build)
// ---------------------------------------------------------------
$backupPath = null;
$backupCount = 0;
$backupDir = $appRoot . '/storage/backups';
if (@is_dir($backupDir) || @mkdir($backupDir, 0777, true)) {
    $backupPath = $backupDir . '/hotfix-' . date('Ymd-His') . '.zip';
    $backup = new ZipArchive();
    if ($backup->open($backupPath, ZipArchive::CREATE | ZipArchive::OVERWRITE) === true) {
        for ($i = 0; $i < $zip->numFiles; $i++) {
            $name = $zip->getNameIndex($i);
            if ($name === false || strpos($name, 'app/') !== 0) {
                continue;
            }
            if (is_file($appRoot . '/' . $name) && $backup->addFile($appRoot . '/' . $name, $name)) {
                $backupCount++;
            }
        }
        $backup->close();
    }
}

// ---------------------------------------------------------------
// Ekstrak paket ke folder aplikasi Laravel
// ---------------------------------------------------------------
$extracted = $zip->extractTo($appRoot);
$fileCount = $zip->numFiles;
$zip->close();
@unlink($tmpZip);

if (!$extracted) {
    http_response_code(500);
    echo '<h2 style="font-family:system-ui,sans-serif;color:#f87171;">Gagal mengekstrak paket. Periksa izin tulis folder aplikasi.</h2>';
    exit;
}

// ---------------------------------------------------------------
// Salin build frontend juga ke root web (kebutuhan hosting ini)
// ---------------------------------------------------------------
$buildCopied = 0;
$buildErrors = [];
$buildSrc = $appRoot . '/public/build';
$webRoot = dirname($appRoot);

$rootLooksLikeWebroot = is_file($webRoot . '/index.php')
    || is_file($webRoot . '/.htaccess')
    || is_dir($webRoot . '/build');
if ($rootLooksLikeWebroot && realpath($webRoot) !== realpath($appRoot)) {
    sq_copy_dir($buildSrc, $webRoot . '/build', $buildCopied, $buildErrors);
}

$cacheCleared = sq_clear_cache($appRoot);

if (function_exists('opcache_reset')) {
    @opcache_reset();
}

// ---------------------------------------------------------------
// Verifikasi hasil
// ---------------------------------------------------------------
$checks = [];
$expService = @file_get_contents($appRoot . '/app/Services/ExpService.php');
$checks[] = [
    'label' => 'ExpService.php memuat rincian total EXP',
    'ok' => is_string($expService) && strpos($expService, 'total_exp_gained') !== false,
];
$checks[] = [
    'label' => 'AchievementService.php memuat preview bonus',
    'ok' => is_string(@file_get_contents($appRoot . '/app/Services/AchievementService.php'))
        && strpos(@file_get_contents($appRoot . '/app/Services/AchievementService.php'), 'previewUnlocks') !== false,
];
$checks[] = [
    'label' => 'IdentityResolver.php tersedia (nama/NISN toleran spasi)',
    'ok' => is_file($appRoot . '/app/Services/IdentityResolver.php'),
];
$checks[] = [
    'label' => 'Manifest build frontend tersedia',
    'ok' => is_file($appRoot . '/public/build/manifest.json'),
];
$checks[] = [
    'label' => 'Build frontend tersalin ke root web',
    'ok' => !$rootLooksLikeWebroot || is_file($webRoot . '/build/manifest.json'),
];

$allOk = true;
foreach ($checks as $check) {
    if (!$check['ok']) {
        $allOk = false;
    }
}

